/*
 Problem: 1979. Find Greatest Common Divisor of Array
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 16.1 MB (67.55%)
 Tags: Array, Math, Number Theory, Euclidean Algorithm, Greatest Common Divisor
*/
class Solution {
public:
    int findGCD(vector<int>& nums) {
        auto [mn, mx] = minmax_element(nums.begin(), nums.end());
        return __gcd(*mn, *mx);
    }
};
